private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
    String degreeStr = degreeText.getText().toString().trim();
    int degree;

    if (degreeStr.isEmpty()) {
        // Nothing was entered, simply restore the value the arc is set to.
        degree = seekArc.getProgress();
    } else {
        try {
            degree = Integer.parseInt(degreeStr);
        } catch (NumberFormatException e) {
            degreeText.setText(getResources().getString(R.string.zero));
            seekArc.setProgress(MIN_DEGREE);
            toastInvalidValueMessage();
            return;
        }
    }

    if (degree > MAX_DEGREE || degree < MIN_DEGREE) {
        degreeText.setText(getResources().getString(R.string.zero));
        seekArc.setProgress(MIN_DEGREE);
        toastInvalidValueMessage();
    } else {
        // The arc resolution matches the degree range, so the entered
        // value can be applied without any rounding.
        seekArc.setProgress(degree);
        // setProgress() only notifies the listener when the value really
        // changes, hence the text is updated here as well to make sure the
        // entered value is always the displayed one.
        degreeText.setText(String.valueOf(degree));
        degreeText.setCursorVisible(false);
    }
}

